/*
 * The sixteen metric-compatible faces the schedule is typeset in — Carlito
 * for Calibri, Liberation for Arial and Times, Caladea for Cambria — as
 * base64 TTF, which is the form pdfmake needs to embed them.
 *
 * They are half a megabyte, and they lived inline in the page, so every
 * visit parsed them and built a stylesheet of sixteen data: URLs before the
 * clinician could type anything. Nothing on the editing screen is set in
 * them: they matter to the PDF, and to the preview's fidelity. So the page
 * now asks for this file only when it needs it, and the browser caches it
 * across visits instead of re-reading it out of the HTML.
 */
window.DOC_FONT_DATA = {"Caladea-Bold":"","Caladea-BoldItalic":"","Caladea-Italic":"","Caladea-Regular":"","Carlito-Bold":"","Carlito-BoldItalic":"","Carlito-Italic":"","Carlito-Regular":"","LiberationSans-Bold":"","LiberationSans-BoldItalic":"","LiberationSans-Italic":"","LiberationSans-Regular":"","LiberationSerif-Bold":"","LiberationSerif-BoldItalic":"","LiberationSerif-Italic":"","LiberationSerif-Regular":""};
